package com.example.payment.architecturetest;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;

import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.junit.AnalyzeClasses;
import com.tngtech.archunit.junit.ArchTest;
import com.tngtech.archunit.lang.ArchRule;

@AnalyzeClasses(packages = "com.example.payment", importOptions = ImportOption.DoNotIncludeTests.class)
class LayeringTest {

    private static final String DOMAIN = "com.example.payment.domain..";
    private static final String APPLICATION = "com.example.payment.application..";
    private static final String INFRASTRUCTURE = "com.example.payment.infrastructure..";
    private static final String APP = "com.example.payment.app..";

    private static final String[] TECHNICAL = {
        "org.springframework..", "com.fasterxml..", "java.io..", "java.nio..", "java.net..", "java.sql..", "javax.."
    };

