    static final ArchRule domain_does_not_depend_on_outer_layers = noClasses()
            .that().resideInAPackage(DOMAIN)
            .should().dependOnClassesThat().resideInAnyPackage(APPLICATION, INFRASTRUCTURE, APP);

    @ArchTest
    static final ArchRule application_does_not_depend_on_infrastructure_or_app = noClasses()
            .that().resideInAPackage(APPLICATION)
            .should().dependOnClassesThat().resideInAnyPackage(INFRASTRUCTURE, APP);

    @ArchTest
    static final ArchRule infrastructure_does_not_depend_on_app = noClasses()
            .that().resideInAPackage(INFRASTRUCTURE)
            .should().dependOnClassesThat().resideInAnyPackage(APP);

    @ArchTest
    static final ArchRule business_code_does_not_use_technical_libraries = noClasses()
            .that().resideInAnyPackage(DOMAIN, APPLICATION)
            .should().dependOnClassesThat().resideInAnyPackage(TECHNICAL);
}
